/**
 * @method
 * @name scwin.search
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.search = async function () {
    /* sdd-asis-lifecycle:begin fn_Search — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const frm = (document.searchForm || { elements: [] });
    if ($c.util.getComponent('cal_startDate').getValue()> $c.util.getComponent('cal_endDate').getValue()) {
        await $c.win.alert('시작일이 종료일보다 이후 일자 입니다.');
        return;
    }
    $c.util.getComponent('dma_SearchReq').set('method', 'searchLinkDisclsApplList');
    frm.action = 'linkDisclsAppl.do';
    await scwin.tx_fn_Search();
    /* sdd-asis-lifecycle:end */
};


