    $c.util.getComponent('dma_SearchReq').set('method', 'linkDisclsApplRegisterForm');
    frm.action = 'linkDisclsAppl.do';
    { const nr = await scwin.tx_fn_Regist(); if (nr && nr.responseJSON && nr.responseJSON.success === true) { $c.win.moveUrl("/jldfil21101/jldfil21101.xml", { "method": 'linkDisclsApplRegisterForm' }); } };
    /* sdd-asis-lifecycle:end */
};


